[96774] = {"Uralter Götze der Gurubashi", {"Bergt einen uralten Götzen der Gurubashi aus der <name>sunkenen Stadt."}},
[96821] = {"Nehmt die Beine in die Hand", {"Tötet 6 Kammschattenkrabbler und 6 Kammschattenlauerer im Süden von Durotar und berichtet anschließend Gar'tok in Klingenhügel davon."}},
[96822] = {"Für die Ehre", {"Sammelt die Räuberstreitaxt, den Räuberbogen und den Räuberschild um Burg Tiragarde und bringt sie anschließend zu Turroc in Klingenhügel zurück."}},
[96825] = {"Diese Frucht beißt zurück", {"Koch Torka in Klingenhügel möchte, dass Ihr 8 Kaktusfeigen im Revier der Grimmhauer westlich der Stadt sammelt."}},
[96873] = {"Ein Dorn im Nacken", {"Pa'zula in Sen'jin möchte, dass Ihr 3 leuchtende Rückstände sammelt. Leuchtende Rückstände können durch das Entzaubern von verhexten Anhängern gefunden werden, die Trolle auf den Echoinseln fallen lassen."}},
[96874] = {"Vom Stachel zur Axt", {"Ug'thok in Orgrimmar möchte, dass Ihr 5 verwitterte Stacheln von Bestien am Donnergrat und 5 raue Schleifsteine für ihn sammelt."}},
[96875] = {"Bestien des Donnergrats", {"Kamari in Orgrimmar möchte, dass Ihr 5 raue Echsenhäute von Wildtieren am Donnergrat und 2 geschmeidige leichte Bälge besorgt."}},
[96876] = {"Ukors verlorener Beutel", {"Bringt den Beutel zu Ukor im Süden von Durotar."}},
[96877] = {"Halikors Huf", {"Bringt Halikors Huf nach Orgrimmar."}},
[96895] = {"Der Argentumabgesandte", {"Findet das Mitglied der Argentumdämmerung in der Nähe des Eingangs von Undercity."}},
[96896] = {"Für die gerechte Sache", {"Beobachtet das Gespräch zwischen Danitha Morr und Leonid Bartholomew dem Geachteten."}},
[96897] = {"Der Kult der Verdammten", {"Tötet 8 dunkle Neophyten und 8 dunkle Vollstrecker in Tirisfal."}},
[96898] = {"Überreste des Krieges", {"Sammelt 12 nekrotische Kristallfragmente in Tirisfal."}},
[96899] = {"Die Bandarionfestung", {"Trefft Leonid Barthalomew in der Bandarionfestung in Tirisfal."}},
[96986] = {"Der Grabritter", {"Besiegt Atrexis den Grabritter in Dalaran für Melisara in Tarrens Mühle."}},
[96988] = {"Quelle der Macht", {"Sammelt 6 gesprungene Wächterkerne in Dalaran für Doktor Martin Felben in Undercity."}},
[97003] = {"Chol'aruk der Verschlinger", {"Bringt den Kopf von Chol'aruk zu Gur'ak im Brachland."}},
[97005] = {"Chol'aruk der Verschlinger", {"Bringt Chol'aruks Kopf zu Bainham im Brachland."}},
[97220] = {"Philmors Bitte", {"Bringt die Torhauslieferung zum Lagerraumeingang in Trias' Käseladen im Handelsdistrikt."}},
[97222] = {"Torhauswaren", {"Tragt die Torhauslieferung die Treppe in Trias' Laden hoch und stellt sie vor der Tür ab."}},
[97223] = {"Blutkrallenmatriarchin", {"Bringt die Eier der Blutkrallenmatriarchin zu Xar'Ti in Sen'jin."}},
[97225] = {"Vergessene Loagötzen", {"Sammelt 8 vergessene Loagötzen auf den Echoinseln. Bringt sie Meister Gadrin in Sen'jin."}},
[97234] = {"Lesezimmer", {"Bringt das verpackte Lesematerial zur Bibliothek von Stormwind."}},
[97236] = {"Fangzahn von Githyiss", {"Bringt den Fangzahn von Githyiss zu jemandem in Aldrassil, der sich für das Studium von Spinnen interessiert."}},
[97237] = {"Regalverlesen", {"Findet die Lesematerialien, die sich irgendwo in der Bibliothek befinden, und kehrt dann zu Roy Lewells im Park von Stormwind zurück."}},
[97242] = {"Yelmaks Mischmasch", {"Sammelt Stecklinge vom Rohrkolben und Speergras, das in der Nähe der fließenden Gewässer im Tal der Ehre wächst, und bringt sie zu Kor'geld in Yelmaks Alchimie und Tränke."}},
[97243] = {"Ruf des Feuers", {"Bringt die Fackel der schlafenden Flamme zu Olariaan Swiftburn im Schrein der Flammen in im Böenbeerentiefland."}},
[97244] = {"Ruf des Feuers", {"Tötet Himmelspriester Faladiel im Böenbeerentiefland und nehmt Faladiels Herz mit."}},
[97245] = {"Ruf des Feuers", {"Findet Kuramaas Zuhause im Shen'darhochland und besiegt den Geist im Kampf. Bringt nach dem Sieg Kuramaas Maske zu Olariaan Swiftburn im Böenbeerentiefland."}},
[97246] = {"Mahlzeit oder Spielzeit", {"Besucht Borstans Feuergrube und sagt ihm, dass Ihr Migis Mittagessen im Auftrag von Thatog persönlich überbringt."}},
[97249] = {"Lieblingsessen", {"Bringt Migi hinter der Feste Grommash sein Mittagessen."}},
[97250] = {"Falsch verurteilt, angemessen vergolten", {"Tötet Soldaten der Allianz, die an der Grenze zu den Marschen von Dustwallow ins Brachland vordringen, und kehrt anschließend zu Grunzer Logmar ins Camp Taurajo zurück."}},
[97253] = {"Teile und Stücke", {"Sammelt 5 Handvoll komplexer Teile vom oberen Piratenlager südlich von Ratchet und kehrt anschließend zurück zu Wrenix dem Jämmerlichen in Ratchet."}},
[97257] = {"Ruf des Feuers", {"Wartet, bis Olariaan mit dem Ritual bei der Kohlenpfanne der Opfergabe beginnt, und folgt seinen Anweisungen.","","Ihr müsst die Ewige Flamme nach Valanaar bringen, bevor die Zeit abläuft."}},
[97275] = {"Whuut Ding will Weile haben", {"Gebt Whuut Yelmaks Trank."}},
[97277] = {"Grund und Gozwin", {"Findet das Lager von Grund und Gozwin in den Hügeln im Nordwesten. Bergt Gozwins Mechanikerlogbuch und tötet den Schneeleopardenpirscher."}},
[97279] = {"Verlorene Waffen", {"Sammelt 6 zurückgelassene Übungswaffen und kehrt dann zu Kzan Thornslash im Höhlenbau zurück."}},
[97281] = {"Ein Sturm braut sich zusammen", {"Bringt die matte Sturmkugel zu Rezlak in der Nähe der Staubwindklamm."}},
[97282] = {"Elektrisierende Aussichten", {"Bringt 5 geladene Donnerechsenorgane zu Rezlak in der Nähe der Staubwindklamm."}},
[97286] = {"Forscherzugang", nil},
[97288] = {"Endlose Qual", {"Bringt den monströsen Kopf zu Apothekermeister Faranell in Undercity."}},
[97289] = {"Endlose Qual", {"Bringt den Kopf des Barons zu Othmars Leiche in Undercity."}},
[97290] = {"Endlose Qual", {"Berichtet Apothekermeister Faranell in Undercity von Euren Erkenntnissen."}},
[97291] = {"Endlose Qual", {"Holt eine giftige Schädelkappe von Tawny Grisette im Handwerksviertel, Blasenkraut in der Nähe des Kräuterkundelehrers und eine Essenz der Pein vom Giftverkäufer im Schurkenviertel für Meisterapotheker Faranell in Undercity."}},
[97292] = {"Endlose Qual", {"Spritzt das zischende Serum für Meisterapotheker Faranell in das System über Othmars Leiche."}},
[97326] = {"Felsen zum Faulenzen", {"Bringt 8 glatte Felsen zu Thra hinter der Feste Grommash."}},
[97485] = {"Traditionen von Thunder Bluff", {"Kauft ein Kräuterbündel von Nida der Kräuterkundigen, ein Bündel Zedernzweige von Nata, der Verkäuferin für Verzauberkunstbedarf, und Sehnenfaden von Mahu, dem Verkäufer für Lederverarbeitungsbedarf, sowie Feuerstein und Zunder von Naal, dem Verkäufer für Kochbedarf.","","Fügt die Gegenstände zusammen und streut das Räucherwerk von der Anhöhe der Jäger."}},
[97538] = {"Pigmente für Farben", {"Tah Winterhoof in Thunder Bluff möchte 30 Mirkkrautsamenkapseln vom Mirkfallonsee."}},
[97558] = {"Häute, Bälge, Membranen", {"Bringt Shelene Rhobart 8 Nachtsaugerflügelmembranen, 6 Schattenhundbälge und 3 Häute eines Murlocs der Finsterflossen."}},
[97891] = {"Zügige Tranklieferung", {"Bringt den instabilen Trank zu Doktor Martin Felben im Apothekarium, bevor die Zeit abläuft."}},
[97894] = {"Geschäfte in Auberdine", {"Seht nach Gorbold Steelhand in Auberdine in Dunkelküste.","","Borgus hat ein Boot am südlichsten Dock im Hafen von Stormwind erwähnt, das Euch dorthin bringen kann."}},
