[97972] = {"Grundlagen des Zeltens: Schneiderei", nil},
[97977] = {"Ruf der Natur", {"Sammelt 4 Totems der Knarzklauen und bringt sie zu Tarindrella."}},
[97979] = {"Das Geschenk der Göttin", {"Wirkt Elunes Licht und Schattenhaftigkeit."}},
[97985] = {"Donnernde Herzen", {"Tötet Sturmherz in Tausend Nadeln und beschafft sein Herz."}},
[98013] = {"Wachsende Streitmacht", {"Tötet für Arbal im Hain der Uralten 12 Myrmidonen der Sturmschuppen, 8 Zauberinnen der Sturmschuppen und 6 Krieger der Sturmschuppen."}},
[98021] = {"Reise zur Späherkuppe", {"Meldet Euch bei Gryan Starkmantel auf der Späherkuppe in Westfall."}},
[98024] = {"Reise nach Crossroads", {"Meldet Euch bei Thork in Crossroads im Brachland."}},
[98025] = {"GEUSCHT: Jai'vhanel", {"Findet und tötet Jai'vhanel. Die schwarze Eule wurde zuletzt nördlich der Ruinen von Ameth'Aran, am Fuß der Berge, gesichtet. Bringt zum Beweis ihres Todes eine ihrer Federn zu Schildwache Glynda Nal'Shea in Auberdine."}},
[98028] = {"Baron Marinous", {"Bringt die getrübte Wasserkugel zu Onu im Hain der Uralten in Dunkelküste."}},
[98042] = {"Ein Blick in den Abgrund", {"Erbeutet ein unvergleichliches Auge von einem Jünger oder Schläger des Twilight-Hammers an der Meistergleve in Dunkelküste und findet in Auberdine jemanden, der bereit ist, es an sich zu nehmen."}},
[98046] = {"Krone der Erde", {"Bringt das ausgelaugte Gefäß zu Lariia im Tempel des Mondes in Darnassus."}},
[98065] = {"Krone der Erde", {"Bringt die Mondbrunnenüberreste zu Tyrande Whisperwind im Tempel des Mondes in Darnassus."}},
[98067] = {"Die Augen der Schildwache", {"Stellt für Schildwache Dalia Sunblade im Tempel des Mondes von Darnassus Wächtereulen am Eingang zu den Tiefen der Burg Cenarius, der Bank von Darnassus, dem Gasthaus auf der Terrasse der Handwerker und am Stadttor auf."}},
[98069] = {"Gestohlene Vorräte vom Freiwindposten", {"Bringt 8 gestohlene Vorräte vom Freiwindposten zu Jandia im Freiwindposten."}},
[98070] = {"Ausgekreischt", {"Tötet 5 kreischende Harpyien, 5 kreischende Wildfedern und 5 kreischende Windruferinnen."}},
[98072] = {"Krokis der Himmel", {"Sammelt 10 makellose Purpurschuppen und bringt sie zu James Halloran in den Hafen von Menethil."}},
[98093] = {"Das Feld säubern", {"Sulhasa im südlichen Brachland möchte, dass Ihr 7 Sturmechsen und 7 Fleischreißerpirscher in der Gegend beseitigt, damit sie sicher von dem Baum herunterkommen kann."}},
[98094] = {"Späherunterstützung", {"Hochexekutorin Darthalia möchte, dass Ihr Todespirscher Masoj südlich von Tarrens Mühle außerhalb von Dun Garok aktualisierte Befehle überbringt."}},
[98095] = {"Nützliche Vorteile", {"Todespirscher Masoj möchte, dass Ihr drei Phiolen des Apothekariums auf Gipfeln rund um das Vorgebirge von Hillsbrad platziert und dann zu ihm zurückkehrt."}},
